-- 2. The data product: contract-compliant rows only.
CREATE OR REFRESH STREAMING TABLE silver.orders (
  order_id STRING NOT NULL COMMENT 'Business key of the order, format ORD-nnnnn',
  customer_id STRING NOT NULL COMMENT 'Customer identifier in the CRM',
  customer_email STRING COMMENT 'Customer e-mail address (personal data, masked outside pii_readers)' MASK ${contracts.catalog}.governance.mask_email,
  country_code STRING NOT NULL COMMENT 'ISO 3166-1 alpha-2 country of the delivery address',
  order_status STRING NOT NULL COMMENT 'Lifecycle status of the order',
  amount DECIMAL(12,2) NOT NULL COMMENT 'Order total including VAT, in EUR',
  currency STRING NOT NULL COMMENT 'ISO 4217 currency code',
  order_ts TIMESTAMP NOT NULL COMMENT 'Moment the customer placed the order (UTC)',
  ingested_at TIMESTAMP NOT NULL COMMENT 'Moment the platform ingested the record; drives the freshness SLA',
  CONSTRAINT orders_pk PRIMARY KEY (order_id)
)
